<?php

namespace Database\Factories;

use App\Models\Certificate;
use App\Models\CertificateTemplate;
use App\Models\ClassName;
use App\Models\User;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * @extends Factory<Certificate>
 *
 * certificate_number and verification_code are generated by the model.
 */
class CertificateFactory extends Factory
{
    protected $model = Certificate::class;

    /**
     * Define the model's default state.
     *
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        return [
            'template_id' => CertificateTemplate::factory(),
            'student_id' => User::factory()->student(),
            'class_id' => ClassName::factory()->completed(),
            'course_id' => fn (array $attributes) => ClassName::find($attributes['class_id'])?->course_id,
            'type' => 'completion',
            'title' => 'Sertifikat Kelulusan',
            'description' => $this->faker->sentence(),
            'issue_date' => now()->subWeek()->toDateString(),
            'expiry_date' => null,
            'metadata' => ['grade' => 'A'],
            'is_valid' => true,
            'issued_by' => User::factory()->admin(),
        ];
    }
}
